STAGES.splice(0,STAGES.length,...BLUEPRINT.stages.map((b,i)=>({...b,n:b.title.split(' — ')[0],en:(i===0?'PROLOGUE':i<=12?'ACT I / X5':'ACT II / X6')+' / '+b.title.split(' — ')[0].toUpperCase(),bossName:b.title.split('Boss: ')[1],element:i<=12?'X5':'X6',color:themeColor[b.theme],tag:b.prompt.match(/Mechanics:\s*([\s\S]*?)Armor Capsule:/)?.[1]||b.title,brief:'Area 1: 0–3200 · Mid-Gate: 3350 · Area 2: 3500–6650 · Boss Arena: 6700–7600. '+(b.prompt.match(/Armor Capsule:\s*([\s\S]*?)Elements:/)?.[1]||''),weapon:REWARDS[b.id]?BLUEPRINT.weapons[REWARDS[b.id][0]].name+' / '+BLUEPRINT.weapons[REWARDS[b.id][1]].name:'DỮ LIỆU CHIẾN DỊCH',weak:WEAK[b.id]||'buster',act:i<=12?1:2,index:i})));
