function freshSave(){return {version:6,char:'x',cleared:[],relics:[],rescues:[],unlocked:{x:[],zero:[]},equipped:{x:'buster',zero:'buster'},armor:'standard',zeroArmor:'zero',parts:{},chips:[],equippedChips:[],souls:0,seconds:0,deaths:0,act:1,stageId:'intro'};}
function loadSlot(n){activeSlot=n;let v;try{v=JSON.parse(localStorage.getItem('mmx_eclipse_save_slot_'+n))}catch{}save={...freshSave(),...(v||{})};ensureUnlocks();campaignAct=save.act;return !!v;}
persist=()=>{save.seconds=playSeconds;try{localStorage.setItem('mmx_eclipse_save_slot_'+activeSlot,JSON.stringify(save))}catch{toast('Không thể lưu trên trình duyệt này',2)}};
loadSlot(1);playSeconds=save.seconds||0;
function hasChip(n){return save.equippedChips?.includes(n);}
function armorReady(id){if(['standard','zero'].includes(id))return true;if(id==='falcon6')return save.cleared.includes('x5_f4_sigma');if(id==='black'&&save.cleared.includes('x6_f1_nzero'))return true;const a=save.parts[id]||[];return a.includes('full')||['head','body','arm','foot'].every(p=>a.includes(p));}
function stats(){const id=save.char==='zero'?save.zeroArmor:save.armor,a={...ARMORS.standard,...ARMORS[id]};if(hasChip('Speedster'))a.speedMult*=1.25;if(hasChip('Jumper'))a.jumpMult*=1.22;if(hasChip('Hyper Dash'))a.dashMult*=1.3;if(hasChip('Energy Saver'))a.wepCostMult*=.5;if(p?.vehicle==='mech'){a.spikeImmune=true;a.dmgMult*=2.5;a.speedMult*=.7;}return a;}
function rank(){const n=save.souls;return n>=3000?'UH':n>=1500?'PA':n>=600?'SA':'GA';}
function chipSlots(){return stats().chipSlots||({GA:1,SA:2,PA:3,UH:4}[rank()]);}
function stageOpen(s){if(s.id==='intro')return true;if(s.act===2&&!save.cleared.includes('x5_f4_sigma'))return false;const i=s.index;if(i<=8||i>=13&&i<=20)return true;if(i===9)return STAGES.slice(1,9).every(s=>save.cleared.includes(s.id));if(i>=10&&i<=12)return save.cleared.includes(STAGES[i-1].id);if(i===21)return STAGES.slice(13,21).every(s=>save.cleared.includes(s.id));return save.cleared.includes(STAGES[i-1].id);}
function nativePath(name){return BLUEPRINT.files.find(f=>f.name.toLowerCase()===name.toLowerCase())?.path||'';}
function nativeImg(name,cls=''){return `<img class="native ${cls}" src="${nativePath(name)}" alt="${name}" loading="lazy">`;}
