map=function(){mode='map';flow=null;resetInput();screen('map');$('mapCount').textContent='ACT '+campaignAct+' · '+save.cleared.length+'/26 · '+rank();$('charBtn').textContent=(save.char==='zero'?'ZERO':'X')+' / '+ARMORS[save.char==='zero'?save.zeroArmor:save.armor].name;const grid=$('stageGrid');grid.replaceChildren();const list=STAGES.filter(s=>s.act===campaignAct);for(const s of list){const b=document.createElement('button');b.className='stageCard'+(stageOpen(s)?'':' locked');b.style.setProperty('--accent',s.color);b.disabled=!stageOpen(s);b.innerHTML=`<div class="art" style="background-image:linear-gradient(0deg,#06101cee,transparent),url(assets/environments/bg-${s.theme}.webp)"><small>${s.index===0?'PROLOGUE':s.index<=8||s.index>=13&&s.index<=20?'MAVERICK':'FORTRESS'} ${save.cleared.includes(s.id)?'✓ CLEAR':!stageOpen(s)?'LOCKED':''}</small><canvas width="160" height="160"></canvas></div><div class="stageText"><b>${s.n}</b><small>${s.bossName}</small></div>`;const g=b.querySelector('canvas').getContext('2d');drawAtlas(g,s.boss,0,80,156,1,1);b.onclick=()=>briefing(s);grid.append(b)}$('finalStage').disabled=false;$('finalStage').textContent=campaignAct===1?'ACT II / X6':'ACT I / X5';$('introReplay').textContent='ALIA / HỒ SƠ';};
function drawAtlas(g,name,frame,x,y,scale=1,dir=1){const m=meta[name],im=A[name];if(!m||!im)return;frame=Math.floor(frame)%m.frames;g.save();g.imageSmoothingEnabled=false;g.translate(x,y);g.scale(scale*(dir<0?-1:1)*(m.facing==='left'?-1:1),scale);if(m.rects){const f=m.rects[frame];g.drawImage(im,f.x,f.y,f.w,f.h,-f.px,-f.py,f.w,f.h)}else g.drawImage(im,frame*m.w,0,m.w,m.h,-m.w/2,-m.h,m.w,m.h);g.restore();}
function characterSelect(next=map){mode='char';dialog('HUNTER SELECT / ACTIVE SLOT '+activeSlot,'CHỌN HUNTER',`<div class="hunterChoices"><div><canvas id="chooseX" width="220" height="170"></canvas><h3>X</h3><p>Charge Buster · Giáp · Vũ khí boss</p></div><div><canvas id="chooseZ" width="220" height="170"></canvas><h3>ZERO</h3><p>Z-Saber · Kỹ thuật · Black Zero</p></div></div>`,[['CHỌN X',()=>{save.char='x';persist();next()},true],['CHỌN ZERO',()=>{save.char='zero';persist();next()}],['TRỞ VỀ',home]]);drawAtlas($('chooseX').getContext('2d'),'x-idle',0,110,145,2);drawAtlas($('chooseZ').getContext('2d'),'zero-idle',0,110,145,2);}
function slots(newGame=false){mode='slots';dialog('DATA TRANSFER / LOCAL SAVE','CHỌN Ô LƯU',`<p>Ba ô lưu riêng. Bản Build 03 được giữ trong dữ liệu cũ và không bị ghi đè.</p><div class="saveSlots">${[1,2,3].map(n=>{let s;try{s=JSON.parse(localStorage.getItem('mmx_eclipse_save_slot_'+n))}catch{}return `<div><b>SLOT ${n}</b><p>${s?`${s.char.toUpperCase()} · ${s.cleared.length}/26 màn · ${s.souls} Souls<br>${Math.floor(s.seconds/60)} phút · ${Object.values(s.parts||{}).flat().length} mảnh giáp`:'DỮ LIỆU TRỐNG'}</p></div>`}).join('')}</div>`,[...[1,2,3].map(n=>['SLOT '+n,()=>{if(newGame&&localStorage.getItem('mmx_eclipse_save_slot_'+n)){dialog('DATA EXISTS','Ô LƯU ĐÃ CÓ TIẾN ĐỘ','<p>Tiếp tục ô lưu này hoặc chọn một ô trống để bắt đầu chiến dịch mới.</p>',[['TIẾP TỤC',()=>{loadSlot(n);playSeconds=save.seconds;characterSelect()}],['CHỌN Ô KHÁC',()=>slots(true)]]);return}loadSlot(n);playSeconds=save.seconds;characterSelect(newGame?()=>cutscene('opening',()=>briefing(STAGES[0])):map)}]),['TRỞ VỀ',home]]);}
briefing=function(s){stage=s;mode='brief';resetInput();const card=s.index>0&&s.index<9?['crescentgrizzly','tidalmakkoeen','voltkraken','shininghotarunicus','spikerosered','darknecrobat','burndinorex','spiralpegacion'][s.index-1]:null;const cap=s.capsules.map(c=>`${ARMORS[c.armor].name} / ${c.part.toUpperCase()} · X ${c.x}, Y ${c.y}`).join('<br>');dialog('ALIA / '+s.en,s.n,`<div class="briefLayout">${nativeImg('x5alia.png','aliaPanel')}<div><p>${s.brief}</p><p><b>Cơ chế:</b> ${s.tag}</p><p><b>Capsule:</b> ${cap||'Không có Light Capsule'}</p><p><b>Boss:</b> ${s.bossName}<br><b>Thưởng:</b> ${s.weapon}</p></div></div>${card?`<div class="cardPair">${nativeImg('rmx5_'+card+'1.png')}${nativeImg('rmx5_'+(card==='shininghotarunicus'?'shininghotatunicus':card)+'2.png')}</div>`:''}<details><summary>BẢN ĐỒ / 7600 × 960</summary><img class="routeMap" src="${s.map}" alt="Sơ đồ ${s.n}"></details>`,[['VỀ BẢN ĐỒ',map],['TRIỂN KHAI',()=>startStage(s),true]]);};
function showArmor(){const back=mode==='play'||mode==='pause'?'pause':mode==='home'?'home':'map';mode='armor';resetInput();const actor=save.char;dialog('EQUIPMENT / '+rank()+' / '+chipSlots()+' CHIP SLOTS','GIÁP & CHIP PARTS',`<div class="armorGrid">${Object.entries(ARMORS).filter(([id,a])=>!a.bossForm&&(actor==='zero'?['zero','black'].includes(id):!['zero','black'].includes(id))).map(([id,a])=>`<button class="armorCard" data-armor="${id}" ${!armorReady(id)?'disabled':''}><canvas width="100" height="135" data-armor-canvas="${id}"></canvas><b>${a.name}</b><small>${armorReady(id)?'SẴN SÀNG':(save.parts[id]||[]).join(' · ')||'CHƯA CÓ MẢNH'}${(actor==='zero'?save.zeroArmor:save.armor)===id?' / ĐANG DÙNG':''}</small><small>SPD ×${a.speedMult} · DMG ×${a.dmgMult}<br>DEF ×${a.defenseMult} · WEP ×${a.wepCostMult}</small></button>`).join('')}</div><h3>CHIP PARTS · ${save.equippedChips.length}/${chipSlots()} khe</h3><div class="chipGrid">${CHIPS.map(([n,s,info])=>`<button data-chip="${n}" ${!save.chips.includes(n)?'disabled':''}>${save.equippedChips.includes(n)?'✓ ':save.chips.includes(n)?'':'🔒 '}${n}<small>${info}</small></button>`).join('')}</div><p>Thu đủ bốn mảnh mới trang bị Blade, Shadow, Falcon X5 hoặc Gaea. Đổi giáp áp dụng ngay; không hồi HP.</p>`,[['ĐÓNG',()=>{mode=back;if(back==='map')map();else if(back==='home')home();else screen('pauseMenu')}]]);document.querySelectorAll('[data-armor-canvas]').forEach(c=>{let id=c.dataset.armorCanvas;if(A['armor-'+id]){const pm=meta['armor-'+id];pm?.rects?drawAtlas(c.getContext('2d'),'armor-'+id,0,50,128,2.3,-1):drawAtlas(c.getContext('2d'),'armor-'+id,0,50,pm?.portrait?103:132,.95,-1)}});document.querySelectorAll('[data-armor]').forEach(b=>b.onclick=()=>{if(!armorReady(b.dataset.armor))return;if(actor==='zero')save.zeroArmor=b.dataset.armor;else save.armor=b.dataset.armor;save.equippedChips=save.equippedChips.slice(0,chipSlots());persist();mode=back;showArmor()});document.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>{const n=b.dataset.chip;if(save.equippedChips.includes(n))save.equippedChips=save.equippedChips.filter(x=>x!==n);else if(save.equippedChips.length<chipSlots())save.equippedChips.push(n);else return toast('Đã dùng hết khe Chip',2);persist();mode=back;showArmor()});}
function showRescue(){mode='rescue';dialog('RESCUE NETWORK / '+rank(),'REPLOID & NIGHTMARE SOULS',`<p>${save.rescues.length} Reploid đã cứu · ${save.souls} Souls · Rank ${rank()}</p><div class="weaponList">${STAGES.filter(s=>s.act===2).map(s=>`<div><b>${s.n}</b><small>${save.rescues.filter(id=>id.startsWith(s.id+':')).length} đã cứu · ${CHIPS.filter(c=>c[1]===s.id).map(c=>c[0]).join(', ')||'Hồi phục'}</small></div>`).join('')}</div>`,[['BẢN ĐỒ',map,true]]);}
function archive(tab='weapons'){mode='archive';dialog('COMPLETE ARCHIVE / V6','KHO TƯ LIỆU X5 × X6',`<div class="archiveTabs">${['weapons','bosses','mechanics','files','audit'].map(t=>`<button data-archive="${t}">${{weapons:'44 WEAPON SHEETS',bosses:'28 BOSS',mechanics:'7 CƠ CHẾ',files:'309 FILE',audit:'ĐỐI CHIẾU'}[t]}</button>`).join('')}</div><input id="archiveSearch" placeholder="Tìm tên, boss, đường dẫn…" aria-label="Tìm tư liệu"><div id="archiveContent"></div>`,[['BẢN ĐỒ',map],['TRANG CHỦ',home]]);const list=tab==='files'?BLUEPRINT.files:tab==='audit'?BLUEPRINT.audit.notes.map(n=>({name:'ASSET AUDIT',text:n})):BLUEPRINT[tab];const show=q=>{$('archiveContent').innerHTML=list.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase())).map(r=>`<article class="archiveRecord"><h3>${r.name}</h3>${r.path?`<img loading="lazy" src="${r.path}" alt="${r.name}"><p>${r.pack.toUpperCase()} / ${r.w} × ${r.h}</p>`:`<p>${r.text}</p>${r.source?`<img loading="lazy" src="${r.source}" alt="${r.name}">`:''}`}</article>`).join('')};show('');$('archiveSearch').oninput=e=>show(e.target.value);document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>archive(b.dataset.archive));}
function options(){mode='options';dialog('SYSTEM / OPTIONS','THIẾT LẬP',`<p>Điều khiển: A/D · Space · C/Shift · Z/J · X/K · Q. E: tương tác/rời xe. R: Giga. S/↓: ngồi hoặc điều hướng dash. ↑: lên/chọn hướng.</p><p>Giữ BẮN để tích lực. Giữ KIẾM để Charge Saber; giữ ↑ khi thả với Blade. Trên cảm ứng dùng các nút ↑ ↓ E GIGA bổ sung.</p><p>Âm thanh tổng hợp bằng Web Audio; nút ÂM THANH bật/tắt. Lưu tự động vào ô đang chọn. Mở toàn màn hình và xoay ngang khi chơi trên điện thoại.</p>`,[['CHỌN NHÂN VẬT',()=>characterSelect()],['KHO TƯ LIỆU',()=>archive()],['TRỞ VỀ',home]]);}
function cutscene(key,next){const map={opening:['scene01.png','ALIA / EURASIA','Mảnh vỡ Eurasia đã rơi xuống Trái Đất. X và Zero tiến vào cao tốc Neo Arcadia, tìm tín hiệu từ một hệ thống phòng thủ chưa tắt.'],act2:['MMX6_Cutscene-01_CrashSite.png','ACT II / NIGHTMARE','Sigma đã bị chặn, nhưng Gate tìm thấy một mảnh dữ liệu Zero. Hiện tượng Nightmare lan khắp tám vùng nghiên cứu. Falcon được phục chế để X trở lại nhiệm vụ.'],zero:['MMX6_Cutscene-03_ZeroRescued.png','ZERO / RESCUED','Bản thể Nightmare tan biến. Zero thật trở về và giải phóng sức mạnh Black Zero.'],highmax:['MMX6_Cutscene-05_HighMaxDefeated.png','HIGH MAX / BREACHED','Hàng rào năng lượng của High Max đã bị phá vỡ. Dấu vết của Gate ngày càng rõ ràng hơn.'],gate:['MMX6_Cutscene-10_GateDefeated.png','GATE / FALLEN','Gate đã ngã xuống. Dữ liệu Nightmare dẫn đến tám cổng quyết đấu và tín hiệu Sigma cuối cùng.'],ending:[save.char==='zero'?'MMX6_Cutscene-13_EndingZero.png':save.rescues.length>=16?'MMX6_Cutscene-12_EndingX_Good.png':'MMX6_Cutscene-11_EndingX_Bad.png','MISSION COMPLETE','Nightmare đã dừng lại. Những Reploid được cứu tiếp tục xây dựng thành phố; X và Zero rời chiến trường khi bình minh trở lại.']};const [img,title,body]=map[key]||map.opening;mode='cutscene';dialog('STORY ARCHIVE / '+key,title,`<div class="cutsceneImage">${nativeImg(img)}</div><p>${body}</p>`,[['TIẾP TỤC',next,true],['BỎ QUA',next]]);}
