function skinName(name){if(!name.startsWith('x-')&&!name.startsWith('zero-'))return name;const zero=name.startsWith('zero-'),armor=zero?save.zeroArmor:save.armor;let rgb=SKIN_COLORS[armor];if(selected!=='buster'&&WEAPONS[selected]){const c=STAGES.find(s=>s.id===selected).color;rgb=[parseInt(c.slice(1,3),16),parseInt(c.slice(3,5),16),parseInt(c.slice(5,7),16)];}if(!rgb||!A[name])return name;const k=name+'@'+armor+'@'+selected;if(A[k])return k;const im=A[name],c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d');g.drawImage(im,0,0);const data=g.getImageData(0,0,c.width,c.height),d=data.data;for(let i=0;i<d.length;i+=4){const r=d[i],gr=d[i+1],b=d[i+2];if(d[i+3]&&(!zero?b>r*1.25&&b>gr*1.10:r>gr*1.5&&r>b*1.35)){const lum=Math.max(r,gr,b)/255;for(let j=0;j<3;j++)d[i+j]=Math.round(rgb[j]*lum);}}g.putImageData(data,0,0);A[k]=c;meta[k]=meta[name];return k;}
