boot=async function(){try{{const AJ=await(await fetch('assets/atlas.json?v=13')).json();Object.assign(meta,AJ,BLUEPRINT.meta);for(const k in AJ)if(AJ[k].tags&&AJ[k].tags[0]==='psx-armor-v2')meta[k]=AJ[k];}environmentManifest=await(await fetch('assets/environments/environment.json?v=13')).json();const tasks=[...Object.keys(meta),...Object.keys(environmentManifest.images)];const missing=[],src=n=>(meta[n]?.asset||environmentManifest.images[n]||'assets/'+n+'.png')+'?v=13';const loadOne=(name,tries=0)=>new Promise(resolve=>{const im=new Image();im.onload=()=>{A[name]=im;resolve()};im.onerror=()=>{if(tries<3)setTimeout(()=>loadOne(name,tries+1).then(resolve),400*(tries+1));else{missing.push(name);resolve();}};im.src=src(name)+(tries?'&r='+tries+'-'+Date.now():'');});let next=0;const worker=async()=>{while(next<tasks.length)await loadOne(tasks[next++]);};await Promise.all(Array.from({length:12},worker));const critical=['x-idle','x-run','x-jump','zero-idle'].filter(n=>missing.includes(n));if(critical.length)throw new Error(critical.join(', '));if(missing.length){console.warn('Missing assets',missing);setTimeout(()=>toast('Thiếu '+missing.length+' ảnh do mạng · tải lại trang để đủ hình',4),1500);}$('load').hidden=true;mode='boot';dialog('MAVERICK HUNTER BASE / SYSTEM BOOT','HUNTER OS · ONLINE',`<p>Archive verified: 309 spritesheets<br>Campaign: 26 sectors · 2 Acts<br>Equipment: 20 capsules · 12 Chip Parts</p><p>X-Buster / Z-Saber systems ready.</p>`,[['START',home,true]]);requestAnimationFrame(frame);}catch(e){$('load').innerHTML='<b>ASSET ERROR</b><p>'+e.message+'</p>';console.error(e)}};
showGuide=function(back='pause'){mode='info';resetInput();dialog('HUNTER MANUAL / BLUEPRINT V6','ĐIỀU KHIỂN',`<table><tr><td>A D / ← →</td><td>Chạy, hướng vào tường rồi nhảy để wall kick.</td></tr><tr><td>Space / W</td><td>Nhảy; giữ khi bay với Falcon X5/Fourth.</td></tr><tr><td>C / Shift</td><td>Dash; giữ ↑ hoặc ↓ khi Mach Dash của Blade.</td></tr><tr><td>Z / J</td><td>Giữ để tích lực, thả để bắn. Q đổi vũ khí.</td></tr><tr><td>X / K</td><td>Chém hoặc kỹ năng Zero. Giữ để Charge Saber; Blade giữ ↑ khi thả.</td></tr><tr><td>E / ↑ gần xe</td><td>Lên/rời Ride Armor, vào Ride Chaser hoặc cổng dịch chuyển.</td></tr><tr><td>R / GIGA</td><td>Giga Attack của giáp; Ultimate dùng Nova Strike.</td></tr><tr><td>P / Esc</td><td>Tạm dừng; dùng Sub-Tank, đổi giáp và Chip.</td></tr></table><p>Mỗi màn có Mid-Checkpoint tại X3350 và Boss Gate tại X6700. Thu đủ bốn mảnh để trang bị giáp. Cứu Reploid để nhận Chips, thu Souls nâng Rank. X dùng Z-Saber ngay từ đầu (nút KIẾM); Zero dùng kỹ thuật đã chọn bằng nút KIẾM.</p>`,[['TRỞ VỀ',()=>{mode=back;screen(back==='pause'?'pauseMenu':'home')},true]]);};
